{
  "architect_scope": "one-R88-structural-factor-only",
  "proposal_mode": "counter_hypothesis",
  "qualitative_hypothesis": {
    "observed_bottleneck": "The active family may fragment causal context by reopening disjoint evidence after executable commitment, making later custody order more influential than integrated evidence.",
    "causal_change": "Close every external-evidence edge after one initial ingress and pass a sealed complete executable capsule directly to terminal emission.",
    "expected_effect": "One-time integrated visibility should reduce order-dependent reinterpretation while shifting evidence timing and downstream revision authority.",
    "falsifier": "all-valid matched majority and strict-median contract, with no score"
  },
  "structural_mutation": {
    "change_count": 1,
    "factor": "single-ingress sealed executable handoff",
    "before": "A four-call executable relay reopens mutually exclusive subsets of common evidence for successive custodians.",
    "after": "A two-call lineage admits all common evidence only at origination, then exposes the final authority solely to the immediately preceding complete executable capsule.",
    "why_structural": "The single-ingress seal removes downstream common-input edges and evidence-conditioned custodial nodes, changing graph depth, evidence timing, visibility, and authority as consequences of one topology factor."
  },
  "mode_certificate": {
    "rejected_assumptions": [
      "Partitioning common evidence into mutually exclusive downstream reentry windows improves reconciliation.",
      "Multiple downstream custodians require independent evidence-conditioned mutation authority over one executable artifact."
    ],
    "forbidden_inherited_mechanism": "disjoint downstream reopening of common external inputs after executable origination",
    "independent_replacement_principle": "One originator receives all common evidence once, seals one complete executable capsule, and every subsequent edge carries only that capsule.",
    "changed_behavioral_dimensions": [
      "external-evidence timing changes from staggered reentry to one-time initial visibility",
      "downstream authority changes from evidence-conditioned revision to sealed-capsule-only emission"
    ],
    "counter_until_promotion": true
  },
  "candidate_structure": {
    "name": "Single-Ingress Sealed Capsule",
    "organization": "two-call sequential lineage with one evidence ingress and one sealed executable edge",
    "information_flow": "The first call receives all six common inputs and emits one complete executable policy capsule. The final call consumes only that immediately preceding capsule, receives no reopened common evidence, and emits one complete policy.",
    "stages": [
      {
        "id": "sealed_single_ingress_lineage",
        "mode": "sequential",
        "calls": [
          {
            "id": "integrated_capsule_origin",
            "role": "single-ingress executable authority",
            "objective": "Integrate the simultaneously visible evidence and obligations into one sealed complete executable policy artifact.",
            "inputs": [
              "task",
              "anchor_policy",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "policy_capsule"
          },
          {
            "id": "sealed_capsule_emit",
            "role": "evidence-blind terminal policy authority",
            "objective": "Consume integrated_capsule_origin without reopened external evidence, preserve its resolved semantics, and emit one complete policy.",
            "inputs": [
              "integrated_capsule_origin"
            ],
            "output_type": "policy"
          }
        ]
      }
    ],
    "final_call_id": "sealed_capsule_emit"
  },
  "compliance": {
    "one_structural_factor_only": true,
    "score_or_trace_content_used": false,
    "policy_code_emitted": false,
    "variants_sampling_or_best_of_n_emitted": false,
    "hardcoding_emitted": false
  }
}
